/*********************************************************************
*
*       Static code
*
**********************************************************************
*/
/*********************************************************************
*
*       _OnTimer
*/
static void _OnTimer(GUI_TIMER_MESSAGE * pTM) {
  static int xPos0;
  static int xPos1;
#if SHOW_SNOW
  static int xPos2;
  static int yPos2;
  static GUI_MEMDEV_Handle hMem;
#endif

  //
  // Create 'Snow' device
  //
#if SHOW_SNOW
  if (hMem == 0) {
    hMem = GUI_MEMDEV_CreateFixed(0, 0, _bmSnow_400x240.XSize, _bmSnow_400x240.YSize, GUI_MEMDEV_NOTRANS, GUI_MEMDEV_APILIST_32, GUICC_M8888I);
    GUI_MEMDEV_Select(hMem);
    GUI_SetBkColor(GUI_TRANSPARENT);
    GUI_Clear();
    GUI_DrawBitmap(&_bmSnow_400x240, 0, 0);
    GUI_MEMDEV_Select(0);
  }
#endif
  //
  // Hills and blue sky
  //
  xPos0 += 1;
  if (xPos0 > _bmHillsWithBlueSky_800x300.XSize) {
    xPos0 -= _bmHillsWithBlueSky_800x300.XSize;
  }
  GUI_SelectLayer(0);
  GUI_DrawBitmap(&_bmHillsWithBlueSky_800x300, xPos0, YPOS_BM);
  GUI_DrawBitmap(&_bmHillsWithBlueSky_800x300, xPos0 - _bmHillsWithBlueSky_800x300.XSize, YPOS_BM);
  //
  // Trees
  //
  xPos1 += 2;
  if (xPos1 > _bmTrees_800x200.XSize) {
    xPos1 -= _bmTrees_800x200.XSize;
  }
  GUI_SelectLayer(1);
  GUI_DrawBitmap(&_bmTrees_800x200, xPos1, 0);
  GUI_DrawBitmap(&_bmTrees_800x200, xPos1 - _bmTrees_800x200.XSize, 0);
  //
  // Snow
  //
#if SHOW_SNOW
  xPos2 += 1;
  if (xPos2 > 400) {
    xPos2 -= 400;
  }
  yPos2 += 2;
  if (yPos2 > 240) {
    yPos2 -= 240;
  }
  GUI_SelectLayer(3);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 - _bmSnow_400x240.XSize, yPos2 - _bmSnow_400x240.YSize);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2,                         yPos2 - _bmSnow_400x240.YSize);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 + _bmSnow_400x240.XSize, yPos2 - _bmSnow_400x240.YSize);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 - _bmSnow_400x240.XSize, yPos2);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2,                         yPos2);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 + _bmSnow_400x240.XSize, yPos2);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 - _bmSnow_400x240.XSize, yPos2 + _bmSnow_400x240.YSize);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2,                         yPos2 + _bmSnow_400x240.YSize);
  GUI_MEMDEV_CopyToLCDAt(hMem, xPos2 + _bmSnow_400x240.XSize, yPos2 + _bmSnow_400x240.YSize);
#endif
  //
  // Keep timer running
  //
  GUI_TIMER_Restart(pTM->hTimer);
}

/*********************************************************************
*
*       _InitBk
*/
static void _InitBk(void) {
  int xSize, ySize;

  //
  // Draw stripes of sky and snow
  //
  GUI_SelectLayer(0);
  xSize = LCD_GetXSize();
  ySize = LCD_GetYSize();
  GUI_SetColor(COLOR_SKY);
  GUI_FillRect(0, 0, xSize - 1, ySize / 2 - 1);
  GUI_SetColor(COLOR_SNOW);
  GUI_FillRect(0, ySize / 2, xSize - 1, ySize - 1);
  //
  // Segger logo
  //
  GUI_SelectLayer(2);
  GUI_SetBkColor(GUI_TRANSPARENT);
  GUI_Clear();
  GUI_PNG_Draw(_acSeggerLogo_120x60, sizeof(_acSeggerLogo_120x60), 20, 10);
  //
  // Automatic sprite animation of deer
  //
  GUI_SPRITE_CreateExAnim(_apbmDeerAnim_181x121, XPOS_DEER, YPOS_DEER, DELAY_DEER, NULL, GUI_COUNTOF(_apbmDeerAnim_181x121), 2);
  //
  // Initialize snow layer with transparency
  //
#if SHOW_SNOW
  GUI_SelectLayer(3);
  GUI_SetBkColor(GUI_TRANSPARENT);
  GUI_Clear();
#endif
}

/*********************************************************************
*
*       Public code
*
**********************************************************************
*/
/*********************************************************************
*
*       MainTask
*/
void MainTask(void) {
  GUI_Init();
  //
  // Check if recommended memory for the sample is available
  //
  if (GUI_ALLOC_GetNumFreeBytes() < RECOMMENDED_MEMORY) {
    GUI_ErrorOut("Not enough memory available."); 
    return;
  }
  //
  // Draw non animated background items
  //
  _InitBk();
  //
  // Animate demo by timer routine
  //
  GUI_TIMER_Create(_OnTimer, 100, 0, 0);
  //
  // Thats all...
  //
  while (1) {
    GUI_Delay(100);
  }
}

